#ifndef FS_INOTIFY_H
#define FS_INOTIFY_H
#include <stdatomic.h>
#include <stdbool.h>
#include <stdint.h>
struct fd;

// inotify: file change notifications.
//
// Events are generated by this file system layer itself, from the system
// calls of guest programs. A watch is on a file (mount and inode number), as
// on Linux. Changes made outside the guest (on iOS: through the Files app)
// are not seen, and neither are writes through a shared memory mapping.

#define IN_ACCESS_ 0x1
#define IN_MODIFY_ 0x2
#define IN_ATTRIB_ 0x4
#define IN_CLOSE_WRITE_ 0x8
#define IN_CLOSE_NOWRITE_ 0x10
#define IN_OPEN_ 0x20
#define IN_MOVED_FROM_ 0x40
#define IN_MOVED_TO_ 0x80
#define IN_CREATE_ 0x100
#define IN_DELETE_ 0x200
#define IN_DELETE_SELF_ 0x400
#define IN_MOVE_SELF_ 0x800
#define IN_ALL_EVENTS_ 0xfff
#define IN_Q_OVERFLOW_ 0x4000
#define IN_IGNORED_ 0x8000
#define IN_ONLYDIR_ 0x01000000
#define IN_DONT_FOLLOW_ 0x02000000
#define IN_EXCL_UNLINK_ 0x04000000
#define IN_MASK_CREATE_ 0x10000000
#define IN_MASK_ADD_ 0x20000000
#define IN_ISDIR_ 0x40000000
#define IN_ONESHOT_ 0x80000000

// number of watches in existence: the hooks do nothing while it is zero
extern atomic_uint inotify_watches;
static inline bool inotify_active(void) {
    return atomic_load_explicit(&inotify_watches, memory_order_relaxed) != 0;
}

struct mount;
// What an event is about: a file, and the directory entry it was reached by.
struct inotify_subject {
    struct mount *mount;
    uint64_t self; // inode number, 0 if there is no such file
    uint64_t parent; // inode number of the directory, 0 if unknown
    uint32_t nlink;
    bool dir;
    char name[256];
};
// Describe the file at path, which has been cut down to its mount already.
void inotify_subject(struct mount *mount, const char *path, struct inotify_subject *subject);
// self_mask goes to watches on the file itself, child_mask (with the name)
// to watches on the directory. The directory is told first, as on Linux.
void inotify_event(const struct inotify_subject *subject, uint32_t self_mask, uint32_t child_mask, uint32_t cookie);
// the same for an open file
void inotify_notify_fd(struct fd *fd, uint32_t mask);
// ties the two halves of a rename together
uint32_t inotify_new_cookie(void);

#endif
